ReplacementContent:
"                         {/* Card 4: Loyalty & Yield */}
                         <div className={`p-3 rounded-xl border flex flex-col gap-1 transition-colors ${
                            isDark ? 'bg-[#161b22] border-[#30363d]' : 'bg-white border-slate-200'
                         }`}>
                            <span className="text-[9px] text-gray-500 font-bold uppercase font-mono">LOYALTY METRICS</span>
                            <span className="text-[11px] font-black text-[#10ac84] uppercase">
                               {previewReceipt.customer_phone ? 'LOYAL MEMBER' : 'POS GUEST'}
                            </span>
                            {previewReceipt.customer_phone && (
                               <span className="text-[9px] font-bold text-gray-400 font-mono">
                                  PH: {previewReceipt.customer_phone}
                               </span>
                            )}
                            <span className="text-[9px] text-gray-500 font-mono">
                               Est. Points: {previewReceipt.points_earned !== undefined ? previewReceipt.points_earned : Math.floor((previewReceipt.total_price || 0) * 0.05)} PTS
                            </span>
                            {previewReceipt.points_redeemed > 0 && (
                               <span className="text-[9px] text-amber-500 font-bold font-mono">
                                  Redeemed: {previewReceipt.points_redeemed} PTS
                               </span>
                            )}
                         </div>"

